class Solution {
    bool isSubseq(const string& sub, int k, const string& s) {
        int targetLen = sub.size() * k;
        int i = 0, j = 0;
        int sLen = s.size();
        while (i < targetLen && j < sLen) {
            if (sub[i % sub.size()] == s[j]) {
                i++;
            }
            j++;
        }
        return i == targetLen;
    }
public:
