class Solution {
    private boolean isSubseq(String sub, int k, String s) {
        int targetLen = sub.length() * k;
        int i = 0, j = 0;
        int sLen = s.length();
        while (i < targetLen && j < sLen) {
            if (sub.charAt(i % sub.length()) == s.charAt(j)) {
                i++;
            }
            j++;
        }
        return i == targetLen;
    }
    public String longestSubsequenceRepeatedK(String s, int k) {
        int[] freq = new int[26];
        for (char c : s.toCharArray()) freq[c - 'a']++;
        List<Character> valid = new ArrayList<>();
        for (int i = 25; i >= 0; i--) {
            if (freq[i] >= k) valid.add((char)('a' + i));
        }
        Queue<String> q = new LinkedList<>();
        q.offer("");
        String ans = "";
        while (!q.isEmpty()) {
            String curr = q.poll();
            for (char c : valid) {
                String nxt = curr + c;
                if (isSubseq(nxt, k, s)) {
                    if (nxt.length() > ans.length() || (nxt.length() == ans.length() && nxt.compareTo(ans) > 0)) {
                        ans = nxt;
                    }
                    q.offer(nxt);
                }
            }
        }
        return ans;
    }
}

var longestSubsequenceRepeatedK = function(s, k) {
  const freq = {};
  for (const c of s) freq[c] = (freq[c] || 0) + 1;
  const valid = Object.keys(freq).filter(c => freq[c] >= k).sort().reverse();

  function isSubseq(sub) {
    let i = 0;
    const targetLen = sub.length * k;
    for (let j = 0; j < s.length && i < targetLen; j++) {
      if (s[j] === sub[i % sub.length]) i++;
    }
    return i === targetLen;
  }

  const q = [''];
  let ans = '';
  while (q.length > 0) {
    const curr = q.shift();
    for (const c of valid) {
      const nxt = curr + c;
      if (isSubseq(nxt)) {
        if (nxt.length > ans.length || (nxt.length === ans.length && nxt > ans)) {
          ans = nxt;
        }
        q.push(nxt);
      }
    }
  }
  return ans;
};
